import Cocoa

final class ConnectionForm:NSView {
 let sites:NSPopUpButton,kind=NSPopUpButton(),name=NSTextField(),host=NSTextField(),user=NSTextField(),port=NSTextField(),password=NSSecureTextField(),key=NSTextField(),ssh=SSHOptionsView()
 let write=NSButton(checkboxWithTitle:"允许 FTP 写入（覆盖非原子）",target:nil,action:nil),time=NSButton(checkboxWithTitle:"保留修改时间（服务器需支持 MFMT）",target:nil,action:nil),permissions=NSButton(checkboxWithTitle:"保留权限（服务器需提供权限及 SITE CHMOD）",target:nil,action:nil)
 let remember=NSButton(checkboxWithTitle:"认证成功后保存服务器密码（钥匙串）",target:nil,action:nil);private let remembered:(Session)->Bool;private let onForget:((Session)throws->Void)?
 let advancedFTP=FTPAdvancedOptionsView();var ftpAdvanced=FTPSiteOptions()
 private let ftpArea=NSView(),note=NSTextField(wrappingLabelWithString:"");private let store:SiteStore;private var previousKind:FileProtocol = .sftp
 var fileProtocol:FileProtocol{FileProtocol.allCases[max(0,kind.indexOfSelectedItem)]}
 init(store:SiteStore,selected:Session?,localPath:String,remembered:@escaping(Session)->Bool={_ in false},onForget:((Session)throws->Void)?=nil){self.store=store;self.remembered=remembered;self.onForget=onForget;sites=NSPopUpButton();super.init(frame:NSRect(x:0,y:0,width:520,height:560))
  sites.addItem(withTitle:"新建站点");for site in store.sites{sites.addItem(withTitle:site.name+" · "+site.identity);sites.lastItem?.representedObject=site};sites.target=self;sites.action = #selector(pick)
  kind.addItems(withTitles:FileProtocol.allCases.map{$0.title});kind.target=self;kind.action = #selector(protocolChanged)
  for (index,pair) in [("已保存站点",sites as NSView),("站点名称",name),("文件协议",kind),("服务器地址 / IP",host),("用户名",user),("端口",port),("FTP 密码",password),("SSH 私钥（可选）",key)].enumerated(){let y=CGFloat(520-index*36);let label=NSTextField(labelWithString:pair.0);label.alignment = .right;label.frame=NSRect(x:0,y:y+3,width:125,height:22);pair.1.frame=NSRect(x:138,y:y,width:372,height:26);addSubview(label);addSubview(pair.1)}
  sites.frame.size.width=260;let delete=NSButton(title:"删除站点…",target:self,action:#selector(deleteSite));delete.frame=NSRect(x:405,y:520,width:105,height:26);addSubview(delete)
  host.placeholderString="server.example.com 或 IP 地址";name.placeholderString="例如：工作服务器";password.placeholderString="仅本次连接使用，不写入站点配置"
  ssh.frame=NSRect(x:0,y:0,width:520,height:180);addSubview(ssh);ftpArea.frame=ssh.frame;addSubview(ftpArea)
  for (i,button) in [write,time,permissions].enumerated(){button.frame=NSRect(x:12,y:145-CGFloat(i*30),width:496,height:25);button.font = .systemFont(ofSize:12);ftpArea.addSubview(button)}
  write.frame.size.width=340;let advanced=NSButton(title:"FTP 高级设置…",target:self,action:#selector(editFTPSettings));advanced.frame=NSRect(x:365,y:145,width:145,height:25);ftpArea.addSubview(advanced)
  let warning=NSTextField(wrappingLabelWithString:"FTP 覆盖时目标会短暂不可用，无法保证原子替换或阻止所有并发改写。不开启写入时仅浏览与下载。FTPS 始终验证证书链及服务器名称。");warning.font = .systemFont(ofSize:11);warning.textColor = .secondaryLabelColor;warning.frame=NSRect(x:12,y:0,width:496,height:78);ftpArea.addSubview(warning)
  remember.font = .systemFont(ofSize:12);remember.frame=NSRect(x:12,y:244,width:380,height:22);remember.target=self;remember.action = #selector(passwordPreferenceChanged);remember.toolTip="仅保存和复用直接目标的普通密码提示，不含跳板机、私钥口令或验证码；取消勾选停止复用，忘记按钮删除保存。";addSubview(remember);let forget=NSButton(title:"忘记已存密码",target:self,action:#selector(forgetPassword));forget.frame=NSRect(x:400,y:244,width:110,height:22);forget.isEnabled=onForget != nil;addSubview(forget)
  note.font = .systemFont(ofSize:11);note.textColor = .secondaryLabelColor;note.frame=NSRect(x:12,y:188,width:496,height:55);addSubview(note)
  load(selected);if let selected=selected,let index=store.sites.firstIndex(where:{$0.identity==selected.identity}){sites.selectItem(at:index+1)}
 }
 required init?(coder:NSCoder){fatalError()}
 func load(_ site:Session?){let proto=site?.fileProtocol ?? .sftp;kind.selectItem(at:FileProtocol.allCases.firstIndex(of:proto)!);previousKind=proto;name.stringValue=site?.name ?? "";host.stringValue=site?.host ?? "";user.stringValue=site?.user ?? "";port.stringValue=String(site?.port ?? proto.defaultPort);key.stringValue=site?.key ?? "";password.stringValue="";remember.state=site.map(remembered)==true ? .on : .off;ssh.load(site?.sshOptions ?? SSHOptions());let options=site?.ftpSettings ?? FTPSiteOptions();ftpAdvanced=options;advancedFTP.load(options);write.state=options.allowNonAtomicWrites ? .on : .off;time.state=options.preserveTime ? .on : .off;permissions.state=options.preservePermissions ? .on : .off;refresh()}
 @objc func pick(){load(sites.selectedItem?.representedObject as? Session)}
 @objc func deleteSite(){guard let site=sites.selectedItem?.representedObject as? Session else{return};let alert=NSAlert();alert.messageText="删除站点“"+site.name+"”？";alert.informativeText="删除本机配置，服务器文件和已建立的连接不受影响。";let forget=NSButton(checkboxWithTitle:"同时忘记该站点保存的服务器密码",target:nil,action:nil);forget.frame=NSRect(x:0,y:0,width:440,height:26);forget.isEnabled=onForget != nil && (try? PasswordEndpoint(site)) != nil;forget.state=forget.isEnabled ? .on : .off;alert.accessoryView=forget;alert.addButton(withTitle:"取消");alert.addButton(withTitle:"删除配置");guard alert.runModal() == .alertSecondButtonReturn else{return};do{if forget.state == .on{try onForget?(site)};try store.remove(site.identity);if let item=sites.selectedItem{sites.menu?.removeItem(item)};sites.selectItem(at:0);load(nil)}catch{let failure=NSAlert();failure.messageText=error.localizedDescription;failure.runModal()}}

 @objc func protocolChanged(){let proto=fileProtocol;if Int(port.stringValue)==previousKind.defaultPort{port.stringValue=String(proto.defaultPort)};previousKind=proto;password.stringValue="";remember.state=(try? endpointSite()).map(remembered)==true ? .on : .off;refresh()}
 private func endpointSite()throws->Session{guard let number=Int(port.stringValue) else{throw SFTPError.message("请先输入有效端口")};return try Session(name:name.stringValue,host:host.stringValue,user:user.stringValue,port:number,key:"",protocolKind:fileProtocol == .sftp ? nil : fileProtocol).validated()}
 @objc func passwordPreferenceChanged(){refresh()}
 @objc func forgetPassword(){do{let site=try endpointSite();_ = try PasswordEndpoint(site);try onForget?(site);remember.state = .off;refresh();note.stringValue="已忘记该站点保存的服务器密码。已建立的连接继续使用本次凭据。"}catch{let a=NSAlert();a.messageText=error.localizedDescription;a.runModal()}}
 private func refresh(){password.placeholderString=remember.state == .on ? "留空可复用本机钥匙串密码；新密码在认证成功后更新" : "仅本次连接使用，不写入站点配置";let isSSH=fileProtocol == .sftp;ssh.isHidden = !isSSH;ftpArea.isHidden=isSSH;key.isEnabled=isSSH;password.isEnabled = !isSSH;note.stringValue=isSSH ? "SFTP 密码、私钥口令及首次主机指纹确认在 SSH 认证需要时弹出。输入不会写入配置或日志。" : fileProtocol == .ftp ? "普通 FTP 不加密密码或文件内容。需要加密时选择显式或隐式 FTPS。密码不写入站点配置；勾选保存后，仅在认证成功时写入钥匙串。" : "FTPS 加密控制及数据通道，不会自动降级到明文 FTP。未勾选保存时，密码仅保留在当前连接内存中。"}
 @objc func editFTPSettings(){advancedFTP.load(ftpAdvanced);let a=NSAlert();a.messageText="FTP 高级设置";a.informativeText="被动连接；加密连接始终验证证书并要求 TLS 1.2 或更新。认证命令优先顺序不改变加密要求。";a.accessoryView=advancedFTP;a.addButton(withTitle:"保存");a.addButton(withTitle:"取消");guard a.runModal() == .alertFirstButtonReturn else{return};do{ftpAdvanced=try advancedFTP.value(base:ftpAdvanced)}catch{let errorAlert=NSAlert();errorAlert.messageText=error.localizedDescription;errorAlert.runModal()}}
 func value(localPath:String)throws->Session{guard let number=Int(port.stringValue) else{throw SFTPError.message("端口必须为整数")};let proto=fileProtocol;var ftpOptions=ftpAdvanced;ftpOptions.allowNonAtomicWrites=write.state == .on;ftpOptions.preserveTime=time.state == .on;ftpOptions.preservePermissions=permissions.state == .on;var site=try Session(name:name.stringValue,host:host.stringValue,user:user.stringValue,port:number,key:proto == .sftp ? key.stringValue : "",options:proto == .sftp ? try ssh.value() : nil,protocolKind:proto == .sftp ? nil : proto,ftpOptions:proto == .sftp ? nil : ftpOptions).validated();if remember.state == .on{_ = try PasswordEndpoint(site)};let old=store.sites.first{$0.identity==site.identity};site.localPath=old?.localPath ?? localPath;site.remotePath=old?.remotePath;return site}
}

final class FTPLoginProgress:NSView,NSWindowDelegate {
 let message=NSTextField(wrappingLabelWithString:"正在验证服务器与登录信息…"),cancelButton=NSButton(title:"取消连接",target:nil,action:nil),spinner=NSProgressIndicator();var onCancel:(()->Void)?;private var connecting=true
 override init(frame:NSRect){super.init(frame:frame);let stack=NSStackView(views:[spinner,message,cancelButton]);stack.spacing=12;stack.translatesAutoresizingMaskIntoConstraints=false;addSubview(stack);spinner.style = .spinning;spinner.controlSize = .small;spinner.startAnimation(nil);message.font = .systemFont(ofSize:12);message.setContentCompressionResistancePriority(.defaultLow,for:.horizontal);cancelButton.target=self;cancelButton.action = #selector(cancel);NSLayoutConstraint.activate([stack.leadingAnchor.constraint(equalTo:leadingAnchor,constant:18),stack.trailingAnchor.constraint(equalTo:trailingAnchor,constant:-18),stack.centerYAnchor.constraint(equalTo:centerYAnchor)])}
 required init?(coder:NSCoder){fatalError()}
 @objc func cancel(){if connecting{onCancel?()}}
 func show(_ state:RemotePaneConnectionState){connecting=state == .connecting;cancelButton.isEnabled=connecting;if !connecting{spinner.stopAnimation(nil)};message.stringValue=state.detail.isEmpty ? state.title : state.detail}
 func windowWillClose(_ notification:Notification){cancel()}
}
